import{_ as t,c as o,o as a,a2 as r}from"./chunks/framework.QTfwLiL8.js";const m=JSON.parse(`{"title":"Seamlessly Switch Calico's Overlay Network in Gardener","description":"","frontmatter":{"aliases":["/blog/2026/02/18/seamlessly-switch-calicos-overlay-network-in-gardener"],"authors":[{"avatar":"https://avatars.githubusercontent.com/DockToFuture","email":"sebastian.stauch@sap.com","login":"DockToFuture","name":"Sebastian Stauch"}],"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/blog/2026/02","linkTitle":"Seamlessly Switch Calico's Overlay Network in Gardener","newsSubtitle":"February 18, 2026","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/blog/2026/02/02-18-seamlessly-switch-calicos-overlay-network-in-gardener.md","to":"02-18-seamlessly-switch-calicos-overlay-network-in-gardener.md"},"publishdate":"2026-02-18","title":"Seamlessly Switch Calico's Overlay Network in Gardener"},"headers":[],"relativePath":"blog/2026/02/02-18-seamlessly-switch-calicos-overlay-network-in-gardener/index.md","filePath":"blog/2026/02/02-18-seamlessly-switch-calicos-overlay-network-in-gardener.md","lastUpdated":null}`),i={name:"blog/2026/02/02-18-seamlessly-switch-calicos-overlay-network-in-gardener/index.md"};function n(s,e,l,c,h,d){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="seamlessly-switch-calico-s-overlay-network-in-gardener" tabindex="-1">Seamlessly Switch Calico&#39;s Overlay Network in Gardener <a class="header-anchor" href="#seamlessly-switch-calico-s-overlay-network-in-gardener" aria-label="Permalink to &quot;Seamlessly Switch Calico&#39;s Overlay Network in Gardener&quot;">​</a></h1><p>Switching networking configurations in a live Kubernetes cluster is a delicate operation where timing is everything. A common scenario for Gardener operators is transitioning a cluster&#39;s Calico networking from an overlay mode (like IPIP) to a non-overlay, native routing mode. Previously, this switch could lead to temporary network disruptions. We&#39;re happy to announce a new feature that ensures this transition is seamless and free of downtime.</p><h3 id="the-challenge-a-race-for-routes" tabindex="-1">The Challenge: A Race for Routes <a class="header-anchor" href="#the-challenge-a-race-for-routes" aria-label="Permalink to &quot;The Challenge: A Race for Routes&quot;">​</a></h3><p>In a non-overlay mode, Calico relies on the cloud provider&#39;s infrastructure to route traffic between nodes. This is typically handled by a route controller that creates the necessary entries in the provider&#39;s route tables.</p><p>The problem was a potential race condition. When an operator disabled the overlay network, the Calico daemonset would begin to roll and reconfigure itself. If this happened <em>before</em> the route controller had finished creating the required routes for all nodes, pods could temporarily lose the ability to communicate with each other, resulting in a period of network downtime. This was especially problematic in large clusters, where route creation can take time or even fail due to cloud provider route table quotas.</p><h3 id="the-solution-a-coordinated-seamless-switch" tabindex="-1">The Solution: A Coordinated, Seamless Switch <a class="header-anchor" href="#the-solution-a-coordinated-seamless-switch" aria-label="Permalink to &quot;The Solution: A Coordinated, Seamless Switch&quot;">​</a></h3><p>To solve this, Gardener now introduces the <code>SeamlessOverlaySwitch</code>, an alpha feature gate in the <code>gardener-extension-networking-calico</code>. When enabled, this feature orchestrates the transition to ensure the underlying network is ready before Calico is reconfigured.</p><p>This is made possible by a foundational enhancement to the <code>aws-custom-route-controller</code>. The controller now updates the standard <code>NetworkUnavailable</code> condition on each Kubernetes node. When it successfully creates the required routes for a node, it sets this condition to <code>False</code> with the reason <code>RouteCreated</code>.</p><p>With this crucial signal in place, the Calico extension can now perform a coordinated switch:</p><ol><li>An operator initiates the switch by disabling the overlay in the Shoot specification.</li><li>With the <code>SeamlessOverlaySwitch</code> feature enabled, the Calico extension detects the requested change but pauses the reconfiguration.</li><li>It begins monitoring the <code>NetworkUnavailable</code> condition on all nodes in the cluster.</li><li>The extension waits until it has verified that <strong>all</strong> nodes are reporting <code>NetworkUnavailable=False</code> with the reason <code>RouteCreated</code>.</li><li>Only once this confirmation is received does the extension proceed with rolling the Calico daemonset to the new non-overlay configuration.</li></ol><p>If the routes are not yet ready on all nodes, the reconciliation process is safely retried, and the existing overlay network remains active and uninterrupted. This guarantees a zero-downtime transition and prevents the cluster from entering a partially configured, inconsistent state. This enhancement is currently available for AWS, with support for other cloud providers to follow.</p><blockquote><p><strong>Side note:</strong> The feature relies on mutating admission policies, which need to be enabled for the shoot cluster.</p></blockquote><hr><h3 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h3><ul><li><a href="https://youtu.be/jScp5zha7Fc?t=1591" target="_blank" rel="noreferrer">Recording: Seamless Overlay Network Switch</a></li><li><a href="https://github.com/gardener/gardener-extension-networking-calico/pull/779" target="_blank" rel="noreferrer">Pull Request: Add <code>SeamlessOverlaySwitch</code> feature gate</a></li><li><a href="https://github.com/gardener/aws-custom-route-controller/pull/411" target="_blank" rel="noreferrer">Pull Request: Set network unavailable condition</a></li></ul>',15)]))}const w=t(i,[["render",n]]);export{m as __pageData,w as default};
